import java.util.Random;

class Card {
    private final String suit;
    private final String rank;

    public Card(String rank, String suit) {
        this.rank = rank;
        this.suit = suit;
    }

    @Override
    public String toString() {
        return rank + " of " + suit;
    }
}

public class CardShuffler {
    // Fisher-Yates Shuffle Algorithm
    public static void fisherYatesShuffle(Card[] deck) {
        Random random = new Random();
        int n = deck.length;

        for (int i = n - 1; i > 0; i--) {
            int j = random.nextInt(i + 1); // Random index from 0 to i (inclusive)
            swap(deck, i, j); // Swap elements
        }
    }

    // Swap method to exchange two elements in the array
    private static void swap(Card[] deck, int i, int j) {
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }

    // Main method to test the shuffle
    public static void main(String[] args) {
        // Create a sample deck of cards
        Card[] deck = {
            new Card("Ace", "Hearts"),
            new Card("2", "Hearts"),
            new Card("3", "Hearts"),
            new Card("4", "Hearts"),
            new Card("5", "Hearts")
        };

        // Print original deck
        System.out.println("Original deck:");
        for (Card card : deck) {
            System.out.println(card);
        }

        // Shuffle the deck
        fisherYatesShuffle(deck);

        // Print shuffled deck
        System.out.println("\nShuffled deck:");
        for (Card card : deck) {
            System.out.println(card);
        }
    }
}


