import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.temporal.ChronoField;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Locale locale = new Locale("es", "ES");

        // Custom month mappings to handle parsing in Java 11
        Map<Long, String> months = new HashMap<>();
        months.put(1L, "ENE");
        months.put(2L, "FEB");
        months.put(3L, "MAR");
        months.put(4L, "ABR");
        months.put(5L, "MAY");
        months.put(6L, "JUN");
        months.put(7L, "JUL");
        months.put(8L, "AGO");
        months.put(9L, "SEP");
        months.put(10L, "OCT");
        months.put(11L, "NOV");
        months.put(12L, "DIC");

        // Build formatter with custom month mapping
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .parseCaseInsensitive()
                .appendPattern("dd")
                .appendText(ChronoField.MONTH_OF_YEAR, months) // Custom month parser
                .appendPattern("yyyy")
                .toFormatter(locale);

        // Parse the input string
        LocalDate date = LocalDate.parse("24ENE1982", formatter);

        System.out.println("Hello world! " + date);
    }
}


