def compute_hash(log_dict: dict):
    return hash(frozenset(log_dict.items()))  # Key-value pairs ensure uniqueness

def deduplicate(logs):
    seen = set()
    for log in logs:
        log_hash = compute_hash(log)
        if log_hash in seen:
            continue
        seen.add(log_hash)
        yield log

# Sample Data
