import pytest
from contextlib import asynccontextmanager
from fastapi.testclient import TestClient
from fastapi import FastAPI, Response, status, Depends
from dependency_injector import containers, providers
from dependency_injector.wiring import Provide, inject


# Greeter class with an override mechanism
class Greeter:
    def greet(self):
        return "Hello"


class FakeGreeter:
    def greet(self):
        return "Hi"


# Define a Dependency Injector container
class Container(containers.DeclarativeContainer):
    greeter = providers.Singleton(Greeter)


@asynccontextmanager
async def _lifespan(app: FastAPI):
    container = Container()
    container.wire(modules=[__name__])
    yield


app = FastAPI(title="Test", lifespan=_lifespan)


@inject
@app.get("/")
async def root(greeter: Greeter = Depends(Provide[Container.greeter])):
    return Response(status_code=status.HTTP_200_OK, content=greeter.greet())


@pytest.fixture
def fake_client():
    container = Container()
    container.greeter.override(providers.Singleton(FakeGreeter))  # Override with FakeGreeter
    app.dependency_overrides[Container.greeter] = lambda: FakeGreeter()

    with TestClient(app) as client:
        yield client

    # Cleanup
    container.greeter.reset_override()
    app.dependency_overrides.clear()


def test_override(fake_client):
    response = fake_client.get("/")
    assert response.text == "Hi"  # Uses FakeGreeter instead of Greeter,"[""import pytest\r\nfrom contextlib import asynccontextmanager\r\nfrom fastapi.testclient import TestClient\r\nfrom fastapi import FastAPI, Response, status, Depends\r\nfrom dependency_injector import containers, providers\r\nfrom dependency_injector.wiring import Provide, inject\r\n\r\n\r\n# Greeter class with an override mechanism\r\nclass Greeter:\r\n    def greet(self):\r\n        return ""Hello""\r\n\r\n\r\nclass FakeGreeter:\r\n    def greet(self):\r\n        return ""Hi""\r\n\r\n\r\n# Define a Dependency Injector container\r\nclass Container(containers.DeclarativeContainer):\r\n    greeter = providers.Singleton(Greeter)\r\n\r\n\r\n@asynccontextmanager\r\nasync def _lifespan(app: FastAPI):\r\n    container = Container()\r\n    container.wire(modules=[__name__])\r\n    yield\r\n\r\n\r\napp = FastAPI(title=""Test"", lifespan=_lifespan)\r\n\r\n\r\n@inject\r\n@app.get(""/"")\r\nasync def root(greeter: Greeter = Depends(Provide[Container.greeter])):\r\n    return Response(status_code=status.HTTP_200_OK, content=greeter.greet())\r\n\r\n\r\n@pytest.fixture\r\ndef fake_client():\r\n    container = Container()\r\n    container.greeter.override(providers.Singleton(FakeGreeter))  # Override with FakeGreeter\r\n    app.dependency_overrides[Container.greeter] = lambda: FakeGreeter()\r\n\r\n    with TestClient(app) as client:\r\n        yield client\r\n\r\n    # Cleanup\r\n    container.greeter.reset_override()\r\n    app.dependency_overrides.clear()\r\n\r\n\r\ndef test_override(fake_client):\r\n    response = fake_client.get(""/"")\r\n    assert response.text == ""Hi""  # Uses FakeGreeter instead of Greeter""]",0

