class BST:
    def __init__(self, val):
        self.value = val
        self.left = None
        self.right = None

    def add_child(self, val):
        if val < self.value:
            if self.left is None:
                self.left = BST(val)
            else:
                self.left.add_child(val)
        elif val > self.value:
            if self.right is None:
                self.right = BST(val)
            else:
                self.right.add_child(val)

    def traverse_pre(self):
        result = []
        self._traverse_pre_helper(result)
        return result

    def _traverse_pre_helper(self, result):
        result.append(self.value)  # Visit root node

        if self.left:
            self.left._traverse_pre_helper(result)  # Traverse left subtree

        if self.right:
            self.right._traverse_pre_helper(result)  # Traverse right subtree


# Example Usage
Tree = BST(5)
Tree.add_child(10)
Tree.add_child(8)
Tree.add_child(2)
Tree.add_child(4)
Tree.add_child(7)

preorder_result = Tree.traverse_pre()
print(preorder_result)  # Expected Output: [5, 2, 4, 10, 8, 7]

python
class BST:
    def __init__(self, val):
        self.value = val
        self.left = None
        self.right = None

    def add_child(self, val):
        if val < self.value:
            if self.left is None:
                self.left = BST(val)
            else:
                self.left.add_child(val)
        elif val > self.value:
            if self.right is None:
                self.right = BST(val)
            else:
                self.right.add_child(val)

    def traverse_pre(self):
        yield self.value  # Visit root node

        if self.left:
            yield from self.left.traverse_pre()  # Traverse left subtree

        if self.right:
            yield from self.right.traverse_pre()  # Traverse right subtree


# Example Usage
Tree = BST(5)
Tree.add_child(10)
Tree.add_child(8)
Tree.add_child(2)
Tree.add_child(4)
Tree.add_child(7)

preorder_result = list(Tree.traverse_pre())
print(preorder_result)  # Expected Output: [5, 2, 4, 10, 8, 7]
