from fastapi import FastAPI, Request, Response
from starlette.middleware.base import BaseHTTPMiddleware
import json

app = FastAPI()

class MetadataMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        response = await call_next(request)

        # Ensure the response is JSON
        if "application/json" in response.headers.get("Content-Type", ""):
            body = b"".join([chunk async for chunk in response.body_iterator])
            try:
                resp_dict = json.loads(body.decode())

                # Ensure OpenAPI schema is not modified
                if "openapi" not in resp_dict:
                    data = {
                        "data": resp_dict,
                        "metadata": {
                            "some_data_key_1": "some_data_value_1",
                            "some_data_key_2": "some_data_value_2",
                            "some_data_key_3": "some_data_value_3"
                        }
                    }
                    body = json.dumps(data, indent=2).encode("utf-8")

                response = Response(
                    content=body,
                    status_code=response.status_code,
                    media_type="application/json"
                )
            except json.JSONDecodeError:
                pass  # Skip non-JSON responses

        return response

# Add middleware to the FastAPI app
app.add_middleware(MetadataMiddleware)

@app.get("/")
async def foo():
    return {"hello": "world!"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000),"[""from fastapi import FastAPI, Request, Response\r\nfrom starlette.middleware.base import BaseHTTPMiddleware\r\nimport json\r\n\r\napp = FastAPI()\r\n\r\nclass MetadataMiddleware(BaseHTTPMiddleware):\r\n    async def dispatch(self, request: Request, call_next):\r\n        response = await call_next(request)\r\n\r\n        # Ensure the response is JSON\r\n        if ""application/json"" in response.headers.get(""Content-Type"", """"):\r\n            body = b"""".join([chunk async for chunk in response.body_iterator])\r\n            try:\r\n                resp_dict = json.loads(body.decode())\r\n\r\n                # Ensure OpenAPI schema is not modified\r\n                if ""openapi"" not in resp_dict:\r\n                    data = {\r\n                        ""data"": resp_dict,\r\n                        ""metadata"": {\r\n                            ""some_data_key_1"": ""some_data_value_1"",\r\n                            ""some_data_key_2"": ""some_data_value_2"",\r\n                            ""some_data_key_3"": ""some_data_value_3""\r\n                        }\r\n                    }\r\n                    body = json.dumps(data, indent=2).encode(""utf-8"")\r\n\r\n                response = Response(\r\n                    content=body,\r\n                    status_code=response.status_code,\r\n                    media_type=""application/json""\r\n                )\r\n            except json.JSONDecodeError:\r\n                pass  # Skip non-JSON responses\r\n\r\n        return response\r\n\r\n# Add middleware to the FastAPI app\r\napp.add_middleware(MetadataMiddleware)\r\n\r\n@app.get(""/"")\r\nasync def foo():\r\n    return {""hello"": ""world!""}\r\n\r\nif __name__ == ""__main__"":\r\n    import uvicorn\r\n    uvicorn.run(app, host=""0.0.0.0"", port=8000)""]",0

