                    } else {
                        setFill(v <= 0.5 ? p1 : p2);
                    }
                }
            };
            transition.setCycleCount(Animation.INDEFINITE);
            sceneProperty().subscribe(scene -> {
                if (scene != null) {
                    transition.play();
                } else {
                    transition.stop();
                }
